# owner: platform
"""Contact sheet for substitute teachers."""

from typing import List

from rosterkit.models import Student


def _check(students: List[Student]) -> None:
    if not students:
        raise ValueError("no students to list")
    for s in students:
        if not s.email:
            msg = f"no email for {s.display_name}"
            raise ValueError(msg)


def _cells(students: List[Student]) -> List[tuple]:
    ordered = sorted(students, key=lambda s: s.display_name)
    return [(s.display_name, s.section, s.email)
            for s in ordered]


def contact_rows(students: List[Student]) -> List[str]:
    """Text rows sorted by name, columns lined up."""
    _check(students)
    cells = _cells(students)
    w = [max(len(c[i]) for c in cells) for i in range(2)]
    return [f"{n:<{w[0]}}  {s:<{w[1]}}  {e}"
            for n, s, e in cells]

