# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def _s(last, first, section, email="a@x.org"):
    return Student("1", last, first, section, email)


class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _s("Young", "Al", "A1", "y@x.org"),
            _s("Ng", "Bo", "Section 2", "n@x.org")
        ])
        self.assertEqual(rows, [
            "Ng, Bo     Section 2  n@x.org",
            "Young, Al  A1         y@x.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ValueError, "Ng, Bo"):
            contact_rows([_s("Ng", "Bo", "A1", None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
